129	new file mode 100644
130	index 000000000..07c4526f0
131	--- /dev/null
132	+++ b/ProjectFortress/src/com/sun/fortress/interpreter/glue/StaticNativeApp.java
133	@@ -0,0 +1,208 @@
134	+/*******************************************************************************
135	+ Probe (climb batch 23's planner, N0's walk half): a builtinPrimitive whose string
136	+ names a static Java method of nativeHelpers ("com.sun.fortress.nativeHelpers.
137	+ Class.method") rather than a glue class.  The method is chosen among the
138	+ class's public static methods of that name by the declaration's own types
139	+ (each declared Fortress type read as its Java type), and called directly:
140	+ each argument unboxed, the result boxed at the declared result type.  A
141	+ method passes self first; a functional method passes its self first too.  A
142	+ helper's raise of a compiled exception class, "fortress.<Api>$<Name>", becomes
143	+ the raise of the library's own <Name>, as Int.overflow() raises it.
144	+ ******************************************************************************/
145	+
146	+package com.sun.fortress.interpreter.glue;
147	+
148	+import static com.sun.fortress.exceptions.ProgramError.error;
149	+import com.sun.fortress.compiler.runtimeValues.FortressImplementationError;
150	+import com.sun.fortress.exceptions.FortressError;
151	+import com.sun.fortress.interpreter.Driver;
152	+import com.sun.fortress.interpreter.evaluator.values.*;
153	+import com.sun.fortress.nodes.*;
154	+import com.sun.fortress.nodes_util.NodeUtil;
155	+
156	+import java.lang.reflect.InvocationTargetException;
157	+import java.lang.reflect.Method;
158	+import java.lang.reflect.Modifier;
159	+import java.math.BigInteger;
160	+import java.util.ArrayList;
161	+import java.util.List;
162	+import java.util.regex.Matcher;
163	+import java.util.regex.Pattern;
164	+
165	+public class StaticNativeApp extends NativeMeth {
166	+    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";
167	+
168	+    /** Does s name a helper (a static method of nativeHelpers), not a glue class? */
169	+    public static boolean isHelperString(String s) {
170	+        return s.startsWith(HELPERS);
171	+    }
172	+
173	+    private final Method m;
174	+    private final Class<?>[] ps;
175	+    private final String result;     // the declared result type's name
176	+    private final int selfAt;        // index of self among the declared parameters, or -1
177	+    private int arity;
178	+
179	+    /** The Java type that carries a value of the named Fortress type, or null. */
180	+    static Class<?> javaFor(String t) {
181	+        if (t == null) return null;
182	+        if (t.equals("ZZ32") || t.equals("NN32") || t.equals("Char")) return int.class;
183	+        if (t.equals("ZZ64") || t.equals("NN64")) return long.class;
184	+        if (t.equals("RR64")) return double.class;
185	+        if (t.equals("RR32")) return float.class;
186	+        if (t.equals("Boolean")) return boolean.class;
187	+        if (t.equals("String") || t.equals("FlatString") || t.equals("JavaString")) return String.class;
188	+        if (t.equals("ZZ")) return BigInteger.class;
189	+        if (t.equals("()")) return void.class;
190	+        return null;
191	+    }
192	+
193	+    static String typeName(TypeOrPattern t) {
194	+        if (t instanceof TupleType && ((TupleType) t).getElements().isEmpty()) return "()";
195	+        if (t instanceof NamedType) return ((NamedType) t).getName().getText();
196	+        return null;
197	+    }
198	+
199	+    static boolean carried(Class<?> c) {
200	+        return c == int.class || c == long.class || c == double.class || c == float.class
201	+            || c == boolean.class || c == String.class || c == BigInteger.class;
202	+    }
203	+
204	+    /**
205	+     * The helper that the string s names for the declaration defn, or an error message.  Among the
206	+     * class's public static methods of that name, it takes the one whose parameters are the
207	+     * declaration's, self first where the declaration has one (a functional method), or one more
208	+     * in front for a dotted method's self, at the Java types that carry the declared types.
209	+     */
210	+    static Object find(String s, Applicable defn) {
211	+        int dot = s.lastIndexOf('.');
212	+        String cls = s.substring(0, dot), name = s.substring(dot + 1);
213	+        Class<?> c;
214	+        try { c = Class.forName(cls); }
215	+        catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
216	+        List<Class<?>> want = new ArrayList<Class<?>>();
217	+        boolean hasSelf = false;
218	+        for (Param p : NodeUtil.getParams(defn)) {
219	+            if (p.getName().getText().equals("self")) { hasSelf = true; continue; }
220	+            want.add(javaFor(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null));
221	+        }
222	+        Class<?> res = javaFor(NodeUtil.getReturnType(defn).isSome()
223	+                               ? typeName(NodeUtil.getReturnType(defn).unwrap()) : null);
224	+        List<Method> fits = new ArrayList<Method>();
225	+        int named = 0;
226	+        for (Method x : c.getMethods()) {
227	+            if (!x.getName().equals(name) || !Modifier.isStatic(x.getModifiers())) continue;
228	+            named++;
229	+            Class<?>[] xs = x.getParameterTypes();
230	+            int off = xs.length - want.size();          // 1: self first
231	+            if (off < 0 || off > 1 || (hasSelf && off != 1)) continue;
232	+            boolean ok = (res == null || x.getReturnType() == res)
233	+                         && (x.getReturnType() == void.class || carried(x.getReturnType()));
234	+            for (int i = 0; ok && i < xs.length; i++) {
235	+                if (!carried(xs[i])) ok = false;
236	+                else if (i >= off && want.get(i - off) != null && xs[i] != want.get(i - off)) ok = false;
237	+            }
238	+            if (ok) fits.add(x);
239	+        }
240	+        if (named == 0) return "Native helper " + s + " names no static method of " + cls + ".";
241	+        if (fits.size() == 1) return fits.get(0);
242	+        if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
243	+        return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
244	+    }
245	+
246	+    StaticNativeApp(Method m, Applicable defn) {
247	+        this.m = m;
248	+        this.ps = m.getParameterTypes();
249	+        this.result = NodeUtil.getReturnType(defn).isSome() ? typeName(NodeUtil.getReturnType(defn).unwrap()) : null;
250	+        int at = -1, i = 0;
251	+        for (Param p : NodeUtil.getParams(defn)) { if (p.getName().getText().equals("self")) at = i; i++; }
252	+        this.selfAt = at;
253	+    }
254	+
255	+    public int getArity() { return arity; }
256	+
257	+    protected void init(Applicable app, boolean isFunctionalMethod) {
258	+        arity = NodeUtil.getParams(app).size() - (isFunctionalMethod ? 1 : 0);
259	+        super.init(app, isFunctionalMethod);
260	+    }
261	+
262	+    /** A function, or a functional method with its self among the arguments: self goes first. */
263	+    public FValue applyToArgs(List<FValue> args) {
264	+        if (selfAt <= 0) return call(args);
265	+        List<FValue> all = new ArrayList<FValue>(args);
266	+        all.add(0, all.remove(selfAt));
267	+        return call(all);
268	+    }
269	+
270	+    /** A dotted method: self first. */
271	+    public FValue applyMethod(FObject self, List<FValue> args) {
272	+        List<FValue> all = new ArrayList<FValue>(args.size() + 1);
273	+        all.add(self);
274	+        all.addAll(args);
275	+        return call(all);
276	+    }
277	+
278	+    private FValue call(List<FValue> args) {
279	+        if (args.size() != ps.length) return error("Native " + m + " given " + args.size() + " arguments");
280	+        Object[] xs = new Object[ps.length];
281	+        for (int i = 0; i < ps.length; i++) xs[i] = unbox(ps[i], args.get(i));
282	+        try {
283	+            return box(m.getReturnType(), result, m.invoke(null, xs));
284	+        }
285	+        catch (InvocationTargetException e) {
286	+            Throwable t = e.getCause();
287	+            FortressError f = raised(t);
288	+            if (f != null) throw f;
289	+            if (t instanceof RuntimeException) throw (RuntimeException) t;
290	+            if (t instanceof Error) throw (Error) t;
291	+            return error(t.toString());
292	+        }
293	+        catch (IllegalAccessException e) {
294	+            return error(e.toString());
295	+        }
296	+    }
297	+
298	+    private static final Pattern RAISE = Pattern.compile("^fortress\\.\\w+\\$(\\w+)$");
299	+
300	+    /** A helper's Utility.makeFortressException("fortress.<Api>$<Name>") names a compiled class;
301	+        under walk it becomes the library's own exception object <Name>. */
302	+    static FortressError raised(Throwable t) {
303	+        if (!(t instanceof FortressImplementationError) || t.getMessage() == null) return null;
304	+        Matcher x = RAISE.matcher(t.getMessage());
305	+        if (!x.matches()) return null;
306	+        return new FortressError((FObject) Driver.getFortressLibrary().getRootValue(x.group(1)));
307	+    }
308	+
309	+    static Object unbox(Class<?> c, FValue v) {
310	+        if (c == int.class) return v instanceof FChar ? ((FChar) v).getChar() : v.getInt();
311	+        if (c == long.class) return v.getLong();
312	+        if (c == double.class) return v.getFloat();
313	+        if (c == float.class) return (float) v.getFloat();
314	+        if (c == boolean.class) return ((FBool) v).getBool();
315	+        if (c == String.class) return v.getString();
316	+        if (c == BigInteger.class) return v.getBigInteger();
317	+        return error("No interpreter value for a Java " + c.getName());
318	+    }
319	+
320	+    /** The result at the declared type: int as ZZ32, NN32 or Char; long as ZZ64 or NN64. */
321	+    static FValue box(Class<?> c, String declared, Object r) {
322	+        if (c == void.class) return FVoid.V;
323	+        if (c == int.class) {
324	+            int i = (Integer) r;
325	+            if ("NN32".equals(declared)) return FNN32.make(i);
326	+            if ("Char".equals(declared)) return FChar.make(i);
327	+            return FInt.make(i);
328	+        }
329	+        if (c == long.class) {
330	+            long l = (Long) r;
331	+            if ("NN64".equals(declared)) return FNN64.make(l);
332	+            return FLong.make(l);
333	+        }
334	+        if (c == double.class) return FFloat.make((Double) r);
335	+        if (c == float.class) return FRR32.make((Float) r);
336	+        if (c == boolean.class) return FBool.make((Boolean) r);
337	+        if (c == String.class) return FString.make((String) r);
338	+        if (c == BigInteger.class) return FBigNum.make((BigInteger) r);
339	+        return error("No interpreter value for a Java " + c.getName());
340	+    }
341	+}
