422	+  assert(overflows(fn () => 65536 DOT 65536), "DOT overflows")
423	+  assert(7 TIMES 6, 42, "TIMES")
424	+  assert(overflows(fn () => 65536 TIMES 65536), "TIMES overflows")
425	+  assert(7 6, 42, "juxtaposition")
426	+  assert(overflows(fn () => 65536 65536), "juxtaposition overflows")
427	+  assert(65536 DOTTIMES 65536, 0, "DOTTIMES wraps")
428	+  assert(7 DIV 2, 3, "DIV")
